#define Pi 3.14159

float SdfSquare(in vec2 uv,in float ss){
    vec2 dist=abs(uv)-vec2(ss,ss);
    return length(max(dist,0.0))+min(max(dist.x,dist.y),0.);
}

float sDFRombus(in vec2 uv,float ss){
    vec2 dist=abs(uv);
    return max(dist.x+dist.y,0.)-ss;
}

float sdHexagon( in vec2 p, in float r )
{
    const vec3 k = vec3(-0.866025404,0.5,0.577350269);

    p = abs(p);

    p -= 2.0 * min(dot(k.xy, p), 0.0) * k.xy;  
    p -= vec2(clamp(p.x, -k.z * r, k.z * r), r);  

    return length(p) * sign(p.y); 
}

float Pulse(in float time,float sp,float maxs){
    return (sin(time*sp)*0.5+0.5)*maxs;
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;

    float angle=radians(iTime*30.);

    mat2 Rot=mat2(cos(angle),sin(angle),-sin(angle),cos(angle));
    mat2 Rot2=mat2(cos(angle),sin(angle),-sin(angle),-cos(angle));

    uv*=Rot;
    uv*=Rot2;
    float SinAnimation=Pulse(iTime,1.0,0.25);

    float Circle=length(uv+SinAnimation);
    float Square=SdfSquare(uv,0.2+SinAnimation);
    float Rombus=sDFRombus(uv,0.2+SinAnimation);
    float Hexagon=sdHexagon(uv,0.2+SinAnimation);


    Circle=0.05/Circle;
    Square=0.01/Square;
    Rombus=0.01/Rombus;
    Hexagon=0.01/Hexagon;


    vec3 col = vec3(0,0,0);

    vec3 NeonColor1=vec3(0.349,0.000,1.000),NeonColor2=vec3(0.000,0.431,1.000),NeonColor3=vec3(1.000,0.302,0.000),
    NeonColor4=vec3(0.000,1.000,0.835),NeonColor5=vec3(1.000,0.000,0.733);


    float IsModTime = mod(iTime,4.0);

    if (IsModTime < 0.5) {
    col += mix(NeonColor1, NeonColor2, uv.x + uv.y * 2.) * Hexagon;
    } else if (IsModTime < 1.0) {
        col += mix(NeonColor2, NeonColor3, uv.x + uv.y) * Square;
    } else if (IsModTime < 2.0) {
        col += mix(NeonColor3, NeonColor4, uv.x + uv.y) * Rombus;
    } else {
        col += mix(NeonColor5,NeonColor2,uv.x) * Circle;
    }

    fragColor = vec4(col,1.0);
}
